<script module lang="ts">
/**
 * The command palette (`design/components/command.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/command.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import * as zag from '@zag-js/dialog'
import { useMachine } from '@zag-js/svelte'

import {
  Portal,
  agentMember,
  attributes,
  joinSlot,
  normalizeProps,
  useDirection,
  watchEffect,
  type IconRole,
} from '@polymorph/svelte'
import { usePresence } from '@polymorph/svelte/motion'
import styles from '@polymorph/recipes/overlays/command.module.css'
import CommandPanel from './CommandPanel.svelte'

export interface CommandItem {
  id: string
  label: string
  icon?: IconRole
  hint?: string
  group?: string
  keywords?: string[]
  disabled?: boolean
  onSelect: () => void
}

export interface CommandProps {
  /**
   * `false` for chained palettes, where the query stays after a command runs.
   */
  closeOnSelect?: boolean
  emptyMessage?: string
  /**
   * The dismiss key label beside the search field (default `esc`). Hosts localize it because a
   * key legend is text too.
   */
  escapeHint?: string
  /**
   * `false` when the app filters the items itself, as with async command sources.
   */
  filter?: false | 'contains'
  items: CommandItem[]
  /**
   * The dialog's accessible name; localized hosts replace the default `Command palette`.
   */
  label?: string
  loading?: boolean
  onOpenChange?: (open: boolean) => void
  /**
   * The app owns the ⌘K binding, because a global hotkey is app policy, not vocabulary.
   */
  open: boolean
  placeholder?: string
}
</script>

<script lang="ts">
let {
  closeOnSelect = true,
  emptyMessage = 'No results',
  escapeHint = 'esc',
  filter = 'contains',
  items,
  label: labelOwn = 'Command palette',
  loading = false,
  onOpenChange,
  open,
  placeholder = 'Type a command…',
}: CommandProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({ label: labelOwn }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
let query = $state('')
let panel = $state<HTMLElement | null>(null)
let scrim = $state<HTMLElement | null>(null)
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  () =>
    ({
      id: uid,
      dir: documentDirection.current,
      open: open,
      'aria-label': label,
      onEscapeKeyDown: (event) => query !== '' && event.preventDefault(),
      onOpenChange: (details) => {
        onOpenChange?.(details.open)
      },
    }) as Partial<zag.Props>,
)
const api = $derived(zag.connect(service, normalizeProps))
const scrimPresent = usePresence(
  () => api.open,
  () => scrim,
  'dialog.scrim',
)
const panelPresent = usePresence(
  () => api.open,
  () => panel,
  'command.panel',
  { side: 'bottom', align: 'center' },
)
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'Command',
    element: () => panel,
    state: () => ({
      open: api.open,
      items: items.map((item) => ({
        id: item.id,
        label: item.label,
        ...(item.disabled === true ? { disabled: true } : {}),
      })),
      query: api.open ? query : '',
    }),
    actions: {
      choose: {
        argument: 'id',
        run: (value) => (
          items.find((item) => item.id === value)?.onSelect(),
          api.open && closeOnSelect && api.setOpen(false)
        ),
      },
      close: () => api.open && api.setOpen(false),
    },
  })
  release1 = () => {
    ran()
  }
}
watchEffect(effect1)
onDestroy(() => release1?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<Portal
    >{#if scrimPresent.current
      }<div
        bind:this={scrim}
        {...attributes(api.getBackdropProps())}
        class={styles.scrim}
        hidden={undefined}
      ></div
    >{/if
    }{#if panelPresent.current
      }<div {...attributes(api.getPositionerProps())} class={styles.positioner}
        ><div
          bind:this={panel}
          {...attributes(api.getContentProps())}
          class={styles.panel}
          hidden={undefined}
          aria-describedby={undefined}
          data-loading={(loading) ? '' : undefined}
          data-member="command"
          ><CommandPanel
            {items}
            {placeholder}
            {escapeHint}
            {filter}
            {loading}
            {emptyMessage}
            onQueryChange={(event) => { query = event }}
            onCommand={() => { closeOnSelect && api.setOpen(false) }}
        /></div
      ></div
    >{/if
  }</Portal
>{/if
}{@render joined.end?.()}
